-- Synthetic devices, canonical website booking, no APNs/provider calls.
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select public.save_owner_mobile_device('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',0,repeat('a',64),repeat('x',100),'sandbox',true,true,false,0,0,'synthetic-device-key-01');
select public.save_owner_mobile_device('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',0,repeat('a',64),repeat('y',100),'sandbox',true,true,false,0,0,'synthetic-device-key-01');
select pg_temp.assert_true(public.owner_mobile_settings('20000000-0000-4000-8000-000000000001')->'devices'->0->>'revision'='1','registration receipt replay does not increment revision');
select pg_temp.assert_true(position('token' in public.owner_mobile_settings('20000000-0000-4000-8000-000000000001')::text)=0,'owner device metadata never returns tokens or ciphertext');
do $$begin begin perform public.save_owner_mobile_device('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',0,repeat('a',64),repeat('x',100),'sandbox',false,true,false,0,0,'synthetic-device-key-01');raise exception 'TEST FAILED changed replay';exception when raise_exception then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;end$$;
reset role;
-- CANONICAL_BOOKING
select pg_temp.assert_true((select count(*)=1 from private.owner_mobile_push where kind='new_request'),'retried website submission queues one generic device alert');
create table pg_temp.push_claim(value jsonb);grant all on pg_temp.push_claim to service_role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into pg_temp.push_claim select public.claim_owner_mobile_push();
select pg_temp.assert_true((select value->>'kind'='new_request' from pg_temp.push_claim),'worker claims new-request intent');
select public.finish_owner_mobile_push((value->>'organization')::uuid,(value->>'id')::uuid,(value->>'lease')::uuid,'accepted','apns_accepted',false) from pg_temp.push_claim;
select pg_temp.assert_true(public.claim_owner_mobile_push() is null,'accepted intent is never claimed twice');
reset role;
-- Isolated temporal fault injection: business booking remains the canonical fixture.
update public.appointments set start_at=now()+interval '20 minutes',arrival_at=now()+interval '60 minutes',end_at=now()+interval '3 hours' where status='reserved';
truncate pg_temp.push_claim;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into pg_temp.push_claim select public.claim_owner_mobile_push();
select pg_temp.assert_true((select value->>'kind'='appointment' from pg_temp.push_claim),'owner reminder follows reserved work start even when customer arrival is later');
reset role;
update private.owner_mobile_push set lease_until=now()-interval '1 second' where state='sending';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.claim_owner_mobile_push() is null,'expired sending lease is uncertain and never blindly retried');
reset role;
select pg_temp.assert_true((select count(*)=1 from private.owner_mobile_push where state='unknown'),'unknown provider outcome retained for reconciliation');
update public.appointments set revision=revision+1 where status='reserved';
update private.owner_mobile_devices set quiet_start=extract(hour from now() at time zone 'America/Chicago')::integer*60+extract(minute from now() at time zone 'America/Chicago')::integer,quiet_end=(extract(hour from now() at time zone 'America/Chicago')::integer*60+extract(minute from now() at time zone 'America/Chicago')::integer+1)%1440;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.claim_owner_mobile_push() is null,'quiet hours retain a reminder without sending');
reset role;
select pg_temp.assert_true((select count(*)=1 from private.owner_mobile_push where state='pending'),'new appointment revision retains one pending intent');
update public.appointments set status='canceled' where status='reserved';
update private.owner_mobile_devices set quiet_start=0,quiet_end=0;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.claim_owner_mobile_push() is null,'canceled visit cannot deliver an old reminder');
reset role;
select pg_temp.assert_true((select count(*)=1 from private.owner_mobile_push where state='skipped'),'stale reminder marked skipped');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
do $$begin begin perform public.owner_mobile_settings('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED tenant access';exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.claim_owner_mobile_push();raise exception 'TEST FAILED worker grant';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select public.disable_owner_mobile_device('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',1);
select public.disable_owner_mobile_device('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',1);
reset role;
select pg_temp.assert_true((select revision=2 and not enabled from private.owner_mobile_devices),'stopping device alerts is repeat-safe');
update private.owner_mobile_devices set enabled=true;
delete from auth.sessions where id='10000000-0000-4000-8000-000000000001';
select pg_temp.assert_true((select not private.mobile_device_active(d) from private.owner_mobile_devices d),'signed-out session cannot receive notifications');
select pg_temp.assert_true(not has_function_privilege('anon','public.owner_mobile_settings(uuid)','execute'),'anonymous device metadata denied');
select pg_temp.assert_true((select count(*)=0 from public.invoices),'notification workflow manufactures no invoice');
rollback;
